#include <stdio.h>

int main(void) {

    int n; long long height[600],best=0;
    scanf("%d",&n);
    for(int i=0;i<n;i++) scanf("%lld",&height[i]);
    for(int l=0;l<n;l++){
        long long low=height[l];
        for(int r=l;r<n;r++){
