#include <stdio.h>
static int a[200000],rising[200000];
int main(void) {

    int n;
    scanf("%d",&n);
    for(int i=0;i<n;i++){
        scanf("%d",&a[i]);
        rising[i]=(i>0&&a[i]>a[i-1])?rising[i-1]+1:1;
    }
    int down=1,best=0;
    for(int i=n-1;i>=0;i--){
        down=(i+1<n&&a[i]>a[i+1])?down+1:1;
        if(down>1&&rising[i]>1&&down+rising[i]-1>best) best=down+rising[i]-1;
    }
    printf("%d\n",best);
    return 0;
}

