Node *order(Node *head) {
    Node *sorted=NULL;
    while(head){
        Node *next=head->next;
        Node **position=&sorted;
        while(*position&&(*position)->value<=head->value)
            position=&(*position)->next;
        head->next=*position;
        *position=head;
        head=next;
    }
    return sorted;
}

