Node *clone(Node *head) {
    static Node *by_id[100001];
    Node *result=NULL, **tail=&result;
    for(Node *p=head;p;p=p->next){
        Node *copy=(Node*)malloc(sizeof *copy);
        *copy=*p;
        copy->next=NULL;
        copy->random=NULL;
        *tail=copy;
        tail=&copy->next;
        by_id[p->id]=copy;
    }
    for(Node *p=head;p;p=p->next)
        if(p->random)by_id[p->id]->random=by_id[p->random->id];
    return result;
}

