}

int deduplicate(char *str) {
    int seen[26]={0},read=0,write=0;
    for(;str[read];read++){
        int index=str[read]-'a';
        if(!seen[index]){
            seen[index]=1;
            str[write++]=str[read];
        }
    }
    str[write]='\0';
    return read-write;
}

