#include <stdio.h>
int main(void) {
    int capacity,n,size=0,misses=0,a[100];
    scanf("%d%d",&capacity,&n);
    for(int i=0;i<n;i++){
        char operation;int id;
        scanf(" %c%d",&operation,&id);
        int at=0;
        while(at<size&&a[at]!=id)at++;
        if(operation=='R'){
            if(at<size){
                for(int j=at+1;j<size;j++)a[j-1]=a[j];
                size--;
            }
        }else if(at==size){
            if(size==capacity){
                for(int j=1;j<size;j++)a[j-1]=a[j];
                size--;
            }
            a[size++]=id;
            misses++;
        }
    }
    printf("%d\n",misses);
    if(!size)puts("EMPTY");
    else{
        for(int i=0;i<size;i++)printf("%s%d",i?" ":"",a[i]);
        puts("");
    }
    return 0;
}

CARD *create(int n) {
    return (CARD *)malloc((size_t)n * sizeof(CARD));
}

int getPoints(CARD *deck, int size) {
    int suits[4]={0},score=0,aces=0,maximum=0;
    for(int i=0;i<size;i++){
        int count=++suits[deck[i].suit-'A'];
        if(count>maximum)maximum=count;
        int face=deck[i].face-'0';
        score+=face?face:10;
        aces+=face==1;
    }
    score+=maximum>=4?5:maximum==3?2:0;
    while(aces--&&score+10<=21)score+=10;
    return score;
}

